using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using RaceDay.Api.Data; using RaceDay.Api.DTOs; using RaceDay.Api.Models; using RaceDay.Api.Services;
namespace RaceDay.Api.Controllers;
[ApiController,Route("api")]
public class EnrollmentsController(RaceDayDbContext db,SessionAuth auth):ControllerBase{
 [HttpGet("events/{eventId:int}/categories")] public async Task<IActionResult> Categories(int eventId)=>Ok(await db.Categories.Where(x=>x.EventId==eventId).ToListAsync());
 [HttpPost("events/{eventId:int}/enrollments")] public async Task<IActionResult> Enroll(int eventId,EnrollmentRequest r){if(!auth.Is(UserRole.Participant))return Forbid();if(!await db.Events.AnyAsync(x=>x.Id==eventId)||!await db.Categories.AnyAsync(x=>x.Id==r.CategoryId&&x.EventId==eventId))return BadRequest("Event/category mismatch");var p=auth.Current!;if(await db.Enrollments.AnyAsync(x=>x.EventId==eventId&&x.ParticipantId==p.Id))return Conflict("Already enrolled");var e=new Enrollment{EventId=eventId,ParticipantId=p.Id,CategoryId=r.CategoryId};db.Enrollments.Add(e);await db.SaveChangesAsync();return Ok(e);}
 [HttpGet("events/{eventId:int}/enrollments")] public async Task<IActionResult> EventEnrollments(int eventId){if(!auth.Is(UserRole.Organiser)||!await db.Events.AnyAsync(x=>x.Id==eventId&&x.OrganiserId==auth.Current!.Id))return Forbid();return Ok(await db.Enrollments.Include(x=>x.Participant).Include(x=>x.Category).Include(x=>x.Result).Where(x=>x.EventId==eventId).Select(x=>new {x.Id,x.EventId,x.ParticipantId,x.CategoryId,ParticipantName=x.Participant.FullName,CategoryName=x.Category.Name,FinishTime=x.Result==null?(TimeSpan?)null:x.Result.FinishTime,FinishingPosition=x.Result==null?(int?)null:x.Result.FinishingPosition}).ToListAsync());}
 [HttpGet("profile/enrollments")] public async Task<IActionResult> Mine(){if(!auth.Is(UserRole.Participant))return Forbid();return Ok(await db.Enrollments.Include(x=>x.Event).Include(x=>x.Category).Include(x=>x.Result).Where(x=>x.ParticipantId==auth.Current!.Id).Select(x=>new {x.Id,x.EventId,x.ParticipantId,x.CategoryId,EventName=x.Event.Name,CategoryName=x.Category.Name,FinishTime=x.Result==null?(TimeSpan?)null:x.Result.FinishTime,FinishingPosition=x.Result==null?(int?)null:x.Result.FinishingPosition}).ToListAsync());}
 [HttpPost("enrollments/{id:int}/result")] public async Task<IActionResult> Result(int id,ResultRequest r){var en=await db.Enrollments.Include(x=>x.Event).SingleOrDefaultAsync(x=>x.Id==id);if(en is null)return NotFound();if(!auth.Is(UserRole.Organiser)||en.Event.OrganiserId!=auth.Current!.Id)return Forbid();en.Result=new Result{EnrollmentId=id,FinishTime=r.FinishTime,FinishingPosition=r.FinishingPosition};await db.SaveChangesAsync();return Ok(en.Result);}
}
